@OptIn(ExperimentalTestApi::class)
class InteractionTest {
 @get:Rule val compose=createAndroidComposeRule<androidx.activity.ComponentActivity>()
 @Test fun inputReflectsHostValueAndMixedCheckboxEmitsOneChange(){var callbacks=0;var checked=0;compose.setContent{val inputMode=LocalInputModeManager.current;SideEffect{inputMode.requestInputMode(InputMode.Keyboard)};var value by remember{mutableStateOf("")};RosemaryTheme {Column{RosemaryInput(value,{value=it;callbacks++},"Name",error=if(value.isBlank())"Required"else null);RosemaryCheckbox(null,{checked++},"All projects")}}};compose.onNode(hasSetTextAction()).performTextInput("Rosemary");compose.onNode(hasSetTextAction()).assertTextEquals("Rosemary");compose.onNodeWithText("Required").assertDoesNotExist();compose.onNodeWithText("All projects").performClick();compose.runOnIdle{assertEquals(1,callbacks);assertEquals(1,checked)}}
 @Test fun pickerCancelDiscardsAndApplyCommits(){var result=LocalDate.of(2026,1,1);compose.setContent{val inputMode=LocalInputModeManager.current;SideEffect{inputMode.requestInputMode(InputMode.Keyboard)};var date by remember{mutableStateOf(result)};RosemaryTheme{RosemaryDate(date,{date=it;result=it},"Date")}};compose.onNodeWithText("2026-01-01").performClick();compose.onNode(hasSetTextAction() and hasContentDescription("Date (YYYY-MM-DD)")).performTextReplacement("2026-02-28");compose.onNodeWithText("Cancel").performClick();compose.runOnIdle{assertEquals(LocalDate.of(2026,1,1),result)};compose.onNodeWithText("2026-01-01").performClick();compose.onNode(hasSetTextAction() and hasContentDescription("Date (YYYY-MM-DD)")).performTextReplacement("2026-02-28");compose.onNodeWithText("Apply").performScrollTo().performClick();compose.runOnIdle{assertEquals(LocalDate.of(2026,2,28),result)}}
 @Test fun modalKeyboardFocusReturnsToTrigger(){compose.setContent{val inputMode=LocalInputModeManager.current;SideEffect{inputMode.requestInputMode(InputMode.Keyboard)};var open by remember{mutableStateOf(false)};RosemaryTheme{Column{RosemaryButton("Open",{open=true});RosemaryDialog(open,"Review",{open=false}){RosemaryButton("Cancel",{open=false})}}}};compose.waitUntil(3000){compose.activity.window.decorView.isAttachedToWindow && compose.activity.window.decorView.hasWindowFocus()};compose.runOnIdle{assertTrue("Host view starts attached and with native focus",compose.activity.window.decorView.isAttachedToWindow && compose.activity.window.decorView.hasWindowFocus())};compose.onNodeWithText("Open").performSemanticsAction(SemanticsActions.RequestFocus){it()};compose.onNodeWithText("Open").assertIsFocused().performKeyInput{pressKey(Key.Enter)};compose.onNodeWithText("Review").assertIsDisplayed();compose.onNodeWithText("Cancel").performSemanticsAction(SemanticsActions.RequestFocus){it()};compose.onNodeWithText("Cancel").assertIsFocused().performKeyInput{pressKey(Key.Tab)};compose.onNodeWithText("Cancel").assertIsFocused();compose.runOnIdle{assertFalse("Background window cannot receive input while modal is active",compose.activity.window.decorView.hasWindowFocus())};compose.onNodeWithText("Cancel").performClick();compose.onNodeWithText("Review").assertDoesNotExist();compose.onNodeWithText("Open").assertIsFocused();compose.waitUntil(3000){compose.activity.window.decorView.hasWindowFocus()};compose.runOnIdle{assertTrue("Native input focus returned",compose.activity.window.decorView.hasWindowFocus())}}
 @Test fun selectKeyboardSkipsDisabledAndRestoresFocus(){var chosen="a";compose.setContent{val inputMode=LocalInputModeManager.current;SideEffect{inputMode.requestInputMode(InputMode.Keyboard)};var value by remember{mutableStateOf("a")};RosemaryTheme{RosemarySelect(value,{value=it;chosen=it},listOf(RosemaryOption("a","Alpha"),RosemaryOption("b","Blocked",false),RosemaryOption("c","Charlie")),"Section")}};compose.onNodeWithText("Alpha").performSemanticsAction(SemanticsActions.RequestFocus){it()};compose.onNodeWithText("Alpha").performKeyInput{pressKey(Key.DirectionDown)};compose.onNodeWithText("Blocked").assertIsNotEnabled();compose.onAllNodesWithText("Alpha").onLast().performKeyInput{pressKey(Key.DirectionDown);pressKey(Key.Enter)};compose.runOnIdle{assertEquals("c",chosen)};compose.onNodeWithText("Charlie").assertIsFocused()}
 @Test fun drawerReopenInterruptsExitAndPopupInheritsLocalTheme(){var setOpen:((Boolean)->Unit)?=null;var inherited=Color.Unspecified;var completions=0;var reduced=false;var setRtl:((Boolean)->Unit)?=null;compose.setContent{var rtl by remember{mutableStateOf(false)};setRtl={rtl=it};val inputMode=LocalInputModeManager.current;SideEffect{inputMode.requestInputMode(InputMode.Keyboard)};var open by remember{mutableStateOf(true)};setOpen={open=it};RosemaryTheme(colors=design.rosemary.compose.generated.RosemaryTokens.dark.copy(primary=Color.Red),reduceMotion=false,direction=if(rtl)LayoutDirection.Rtl else LayoutDirection.Ltr){val motion=RosemaryTheme.reducedMotion;SideEffect{reduced=motion};Column{RosemaryDrawer(open,"Details",{open=false},onAnimationFinished={completions++}){RosemaryText("Drawer body")};RosemaryPopover(true,{},trigger={}){val color=RosemaryTheme.colors.primary;SideEffect{inherited=color};RosemaryText("Popover body")}}}};compose.mainClock.autoAdvance=false;val initialLeft=compose.onNodeWithText("Drawer body").fetchSemanticsNode().boundsInRoot.left;compose.runOnIdle{setOpen!!(false)};compose.mainClock.advanceTimeBy(64);if(!reduced)assertTrue("Drawer has a real exit intermediate frame",compose.onNodeWithText("Drawer body").fetchSemanticsNode().boundsInRoot.left>initialLeft);compose.runOnIdle{setOpen!!(true)};compose.mainClock.advanceTimeBy(400);compose.onNodeWithText("Drawer body").assertExists();compose.runOnIdle{assertEquals(Color.Red,inherited)};compose.runOnIdle{setOpen!!(false)};compose.mainClock.advanceTimeBy(400);compose.onNodeWithText("Drawer body").assertDoesNotExist();compose.runOnIdle{assertTrue(completions>0);setRtl!!(true);setOpen!!(true)};compose.mainClock.advanceTimeBy(400);val rtlOpenLeft=compose.onNodeWithText("Drawer body").fetchSemanticsNode().boundsInRoot.left;compose.runOnIdle{setOpen!!(false)};compose.mainClock.advanceTimeBy(64);if(!reduced)assertTrue("RTL drawer exits toward inline end",compose.onNodeWithText("Drawer body").fetchSemanticsNode().boundsInRoot.left<rtlOpenLeft)else compose.onNodeWithText("Drawer body").assertDoesNotExist();compose.mainClock.advanceTimeBy(400);compose.mainClock.autoAdvance=true}
 @Test fun extremeYearViewsAndTimeCancelPreserveHost(){var result=LocalDate.of(1,1,1);var time=LocalTime.of(0,0);compose.setContent{val inputMode=LocalInputModeManager.current;SideEffect{inputMode.requestInputMode(InputMode.Keyboard)};RosemaryTheme{RosemaryDate(result,{result=it},"Date",time=time,onTimeChange={time=it})}};compose.onNodeWithText("0001-01-01").performClick();compose.onAllNodesWithText("1").onFirst().performClick();compose.onNode(hasSetTextAction() and hasContentDescription("Year")).performTextReplacement("9999");compose.onAllNodesWithText("9999").onLast().performScrollTo().performClick();compose.onNodeWithText("12").performScrollTo().performClick();compose.onNodeWithText("Next month").assertIsNotEnabled();compose.onNode(hasSetTextAction() and hasContentDescription("Time (HH:mm)")).performTextReplacement("23:59");compose.onNodeWithText("Cancel").performScrollTo().performClick();compose.runOnIdle{assertEquals(LocalDate.of(1,1,1),result);assertEquals(LocalTime.MIDNIGHT,time)}}
}
